using System.Diagnostics;
using System.Security.Cryptography;
using BmsDesktop.Infrastructure;
using Npgsql;
namespace BmsDesktop.Backup;
public sealed class BackupService { private readonly DatabaseConfig _cfg; private readonly Database _db; public BackupService(DatabaseConfig cfg,Database db){_cfg=cfg;_db=db;} public async Task<string> CreateFullAsync(string pgDumpPath,string destination,Guid actor){Directory.CreateDirectory(Path.GetDirectoryName(destination)??".");var psi=new ProcessStartInfo(pgDumpPath){UseShellExecute=false,RedirectStandardError=true,CreateNoWindow=true};psi.Environment["PGPASSWORD"]=_cfg.Password;foreach(var a in new[]{"--format=custom","--no-owner","--no-acl","--host",_cfg.Host,"--port",_cfg.Port.ToString(),"--username",_cfg.Username,"--file",destination,_cfg.Database})psi.ArgumentList.Add(a);using var p=Process.Start(psi)??throw new InvalidOperationException("pg_dump tidak dapat dijalankan.");await p.WaitForExitAsync();var err=await p.StandardError.ReadToEndAsync();if(p.ExitCode!=0)throw new InvalidOperationException("Backup gagal: "+err);await using var fs=File.OpenRead(destination);var hash=Convert.ToHexString(await SHA256.HashDataAsync(fs)).ToLowerInvariant();await using var cn=await _db.OpenAsync();await using var cmd=new NpgsqlCommand("insert into backup_history(id,file_name,backup_type,created_by,sha256,status) values(@id,@f,'FULL',@u,@h,'VERIFIED')",cn);cmd.Parameters.AddWithValue("id",Guid.NewGuid());cmd.Parameters.AddWithValue("f",Path.GetFileName(destination));cmd.Parameters.AddWithValue("u",actor);cmd.Parameters.AddWithValue("h",hash);await cmd.ExecuteNonQueryAsync();return hash;} }
